import React, { useEffect, useState } from 'react';
import axios from 'axios';

interface JobSeeker {
    id: number;
    firstName: string;
    lastName: string;
    email: string;
    phone: string;

}

const JobSeekers: React.FC = () => {
    const [jobSeekers, setJobSeekers] = useState<JobSeeker[]>([]);
    const [loading, setLoading] = useState<boolean>(true);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        const fetchJobSeekers = async () => {
            try {
                const response = await axios.get('http://localhost:8000/app/jobSeekers', {
                    headers: {
                        Authorization: `Bearer ${localStorage.getItem('token')}`
                    }
                });
                setJobSeekers(response.data);
            } catch (err) {
                console.error('Error fetching job seekers:', err);
                setError('Failed to fetch job seekers');
            } finally {
                setLoading(false);
            }
        };

        fetchJobSeekers();
    }, []);

    if (loading) {
        return <div>Loading...</div>;
    }

    if (error) {
        return <div>{error}</div>;
    }

    return (
        <div className="container mt-5">
            <h1 className="text-center">Job Seekers</h1>
            <div className="card p-4 mt-3">
                <ul className="list-group">
                    {jobSeekers.map(seeker => (
                        <li key={seeker.id} className="list-group-item">
                            {seeker.firstName} {seeker.lastName} - {seeker.email} - {seeker.phone}
                        </li>
                    ))}
                </ul>
            </div>
        </div>
    );
};

export default JobSeekers;
